// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List actions (optionally by status)
	// (GET /api/actions)
	GetActions(w http.ResponseWriter, r *http.Request, params GetActionsParams)
	// Update an action status
	// (POST /api/actions/{id}/status)
	PostActionStatus(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Get the current draft or confirmed FinancialBaseline
	// (GET /api/baselines/current)
	GetCurrentBaseline(w http.ResponseWriter, r *http.Request)
	// Transfer-aware monthly income/expense totals for baseline charts
	// (GET /api/baselines/monthly-cashflow)
	GetBaselineMonthlyCashflow(w http.ResponseWriter, r *http.Request, params GetBaselineMonthlyCashflowParams)
	// Recompute and persist a draft FinancialBaseline
	// (POST /api/baselines/recompute)
	PostBaselinesRecompute(w http.ResponseWriter, r *http.Request)
	// Correct one baseline metric and create a new draft version
	// (POST /api/baselines/{id}/adjust)
	PostBaselineAdjust(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Confirm a draft FinancialBaseline
	// (POST /api/baselines/{id}/confirm)
	PostBaselineConfirm(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List system (and user) categories
	// (GET /api/categories)
	GetCategories(w http.ResponseWriter, r *http.Request)
	// Send a chat message and receive a grounded finance answer
	// (POST /api/chat)
	PostChat(w http.ResponseWriter, r *http.Request)
	// Stream a grounded finance answer as server-sent events
	// (POST /api/chat/stream)
	PostChatStream(w http.ResponseWriter, r *http.Request)
	// Apply high-confidence pattern category suggestions on the Needs review queue
	// (POST /api/classifications/apply-suggestions)
	PostClassificationApplySuggestions(w http.ResponseWriter, r *http.Request)
	// List high-impact classifications awaiting review
	// (GET /api/classifications/queue)
	GetClassificationQueue(w http.ResponseWriter, r *http.Request)
	// Correct a transaction category and optionally save a merchant rule
	// (POST /api/classifications/{transaction_id}/correct)
	PostClassificationCorrect(w http.ResponseWriter, r *http.Request, transactionId openapi_types.UUID)
	// List decisions (newest first)
	// (GET /api/decisions)
	GetDecisions(w http.ResponseWriter, r *http.Request, params GetDecisionsParams)
	// Create a decision with one measurable action
	// (POST /api/decisions)
	PostDecisions(w http.ResponseWriter, r *http.Request)
	// Create a 90-day liquidity forecast from the current baseline
	// (POST /api/forecasts)
	PostForecasts(w http.ResponseWriter, r *http.Request)
	// Get the latest forecast for the current baseline
	// (GET /api/forecasts/latest)
	GetLatestForecast(w http.ResponseWriter, r *http.Request)
	// Get a forecast by id
	// (GET /api/forecasts/{id})
	GetForecast(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List scenarios for a forecast
	// (GET /api/forecasts/{id}/scenarios)
	GetForecastScenarios(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Run a typed scenario against a forecast
	// (POST /api/forecasts/{id}/scenarios)
	PostForecastScenario(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Health check
	// (GET /api/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// List recent import runs
	// (GET /api/imports)
	GetImports(w http.ResponseWriter, r *http.Request, params GetImportsParams)
	// Commit a Sparkasse CSV import
	// (POST /api/imports)
	PostImports(w http.ResponseWriter, r *http.Request)
	// Preview a Sparkasse CSV import without writing transactions
	// (POST /api/imports/preview)
	PostImportsPreview(w http.ResponseWriter, r *http.Request)
	// Get an import run by id
	// (GET /api/imports/{id})
	GetImport(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Roll back a committed import run and delete its transactions
	// (POST /api/imports/{id}/rollback)
	PostImportRollback(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List available LLM models for chat
	// (GET /api/llm/models)
	GetLLMModels(w http.ResponseWriter, r *http.Request)
	// List all recurring series
	// (GET /api/recurring)
	GetRecurring(w http.ResponseWriter, r *http.Request)
	// List uncertain recurring series awaiting review
	// (GET /api/recurring/uncertain)
	GetUncertainRecurring(w http.ResponseWriter, r *http.Request)
	// Confirm an uncertain recurring series
	// (POST /api/recurring/{id}/confirm)
	PostRecurringConfirm(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List sample member transactions for a recurring series
	// (GET /api/recurring/{id}/members)
	GetRecurringMembers(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params GetRecurringMembersParams)
	// Dismiss an uncertain recurring series
	// (POST /api/recurring/{id}/reject)
	PostRecurringReject(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List Money Reviews (newest first)
	// (GET /api/reviews)
	GetMoneyReviews(w http.ResponseWriter, r *http.Request, params GetMoneyReviewsParams)
	// Generate a Money Review pinned to the current (or given) baseline
	// (POST /api/reviews)
	PostMoneyReviews(w http.ResponseWriter, r *http.Request)
	// Get a Money Review by id
	// (GET /api/reviews/{id})
	GetMoneyReview(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Confirm a Money Review
	// (POST /api/reviews/{id}/confirm)
	PostMoneyReviewConfirm(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List transactions
	// (GET /api/transactions)
	GetTransactions(w http.ResponseWriter, r *http.Request, params GetTransactionsParams)
	// Mark or unmark a transaction as a one-off (excluded from typical-spend math)
	// (POST /api/transactions/{transaction_id}/one-off)
	PostTransactionOneOff(w http.ResponseWriter, r *http.Request, transactionId openapi_types.UUID)
	// List suggested internal transfer pairs awaiting review
	// (GET /api/transfers/candidates)
	GetTransferCandidates(w http.ResponseWriter, r *http.Request)
	// Confirm a suggested transfer pair (exclude legs from household cashflow)
	// (POST /api/transfers/{id}/confirm)
	PostTransferConfirm(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Reject a suggested transfer pair
	// (POST /api/transfers/{id}/reject)
	PostTransferReject(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
}

// Unimplemented server implementation that returns http.StatusNotImplemented for each endpoint.

type Unimplemented struct{}

// List actions (optionally by status)
// (GET /api/actions)
func (_ Unimplemented) GetActions(w http.ResponseWriter, r *http.Request, params GetActionsParams) {
	w.WriteHeader(http.StatusNotImplemented)
}

